// seed-demo.js
// Fills a database kept for the demo with a realistic hospital ward: an
// owner, a manager and twelve nurses and healthcare assistants; three
// qualifications; day, evening and night shifts with coverage every day;
// availability with hard limits and soft wishes; four published weeks
// generated by the real engine; and a two-week draft.
//
//   npm run seed:demo -- --yes
//
// It refuses to run unless MONGODB_URI names a database ending in "-demo",
// and unless --yes is given. Each run first removes the previous run's ward,
// found by its fixed id, and touches nothing else. The steps live in
// scripts/demo/, in the order runSeed.js calls them.

// Load backend/.env the way the app does - a variable already set in your
// shell wins over the file - before anything reads the environment.
try {
  process.loadEnvFile(new URL('../.env', import.meta.url));
} catch {
  // No .env at all. The guard explains what is missing.
}

const { main } = await import('./demo/runSeed.js');
process.exitCode = await main(process.argv.slice(2), process.env);
